#pragma once
// Single-writer materialization service; concurrent bounded snapshot readers.
#include "anaiero/contracts/runtime_events.hpp"
#include "anaiero/contracts/service_extension.hpp"
#include <mutex>
namespace anaiero::runtime {
class ColonyProjector {
  mutable std::mutex mutex_;
  ColonyState state_{};
  contracts::IServiceExtension* extension_=nullptr;
  static bool same_key(const MetricValue& a, const Observation& b) noexcept {
    return a.colony==b.colony&&a.animon==b.animon&&a.metric==b.metric&&a.source==b.source&&a.source_epoch==b.source_epoch;
  }
public:
  // Configure extension before starting threads. Never invoke it under lock.
  void set_extension(contracts::IServiceExtension* ext) noexcept {extension_=ext;}
  // Restore is a startup-only operation. Validate every cursor and metric before
  // replacing the initially empty projection; no observer callbacks are emitted.
  Status restore(const ColonyState& next)noexcept {
    if(next.count>kMaxMetrics||next.sources>kMaxSources||next.revision!=next.committed_updates||
       next.sequence_gaps>next.committed_updates)return Status::invalid;
    for(std::size_t i=0;i<next.sources;++i){const auto& c=next.cursors[i];
      if(!c.id||!c.clock_domain||!c.epoch||!c.has_sequence||!c.last_sequence)return Status::invalid;
      for(std::size_t j=0;j<i;++j)if(next.cursors[j].id==c.id&&next.cursors[j].epoch==c.epoch)return Status::invalid;
    }
    for(std::size_t i=0;i<next.count;++i){const auto& m=next.values[i];
      if(!m.colony||!m.source||!m.source_epoch||!m.sequence||!valid_metric(m.metric)||!valid_origin(m.origin)||
         static_cast<unsigned>(m.quality)>static_cast<unsigned>(Quality::stale))return Status::invalid;
      bool bound=false;for(std::size_t j=0;j<next.sources;++j){const auto& c=next.cursors[j];
        if(c.id==m.source&&c.epoch==m.source_epoch&&m.sequence<=c.last_sequence&&m.acquired_ns<=c.last_acquired_ns)bound=true;}
      if(!bound)return Status::invalid;
      for(std::size_t j=0;j<i;++j){const auto& p=next.values[j];
        if(p.colony==m.colony&&p.animon==m.animon&&p.metric==m.metric&&p.source==m.source&&p.source_epoch==m.source_epoch)return Status::invalid;}
    }
    if((next.count==0)!=(next.sources==0)||(next.revision==0)!=(next.count==0))return Status::invalid;
    std::lock_guard<std::mutex> lock(mutex_);
    if(state_.revision||state_.count||state_.sources)return Status::invalid;
    state_=next;return Status::ok;
  }
  // Single-owner admission check: do not append an impossible observation to
  // the durable evidence log. Apply must follow on the same writer owner.
  Status can_apply(const Observation& o) const noexcept {
    if(!valid_observation(o))return Status::invalid;
    std::lock_guard<std::mutex> lock(mutex_);
    std::size_t source_index=state_.sources;
    for(std::size_t i=0;i<state_.sources;++i)
      if(state_.cursors[i].id==o.source &&
         state_.cursors[i].epoch==o.source_epoch){source_index=i;break;}
    if(source_index==kMaxSources)return Status::source_full;
    if(source_index<state_.sources){
      const auto& cursor=state_.cursors[source_index];
      if(cursor.clock_domain!=o.clock_domain)return Status::unauthorized;
      if(cursor.has_sequence){
        if(o.sequence==cursor.last_sequence)return Status::duplicate;
        if(o.sequence<cursor.last_sequence||o.acquired_ns<cursor.last_acquired_ns)
          return Status::out_of_order;
      }
    }
    for(std::size_t i=0;i<state_.count;++i)if(same_key(state_.values[i],o))return Status::ok;
    return state_.count==kMaxMetrics?Status::state_full:Status::ok;
  }
  Status apply(const Observation& o) noexcept {
    if(!valid_observation(o))return Status::invalid;
    std::uint64_t revision=0;
    {
    std::lock_guard<std::mutex> lock(mutex_);
    std::size_t source_index=state_.sources;
    for(std::size_t i=0;i<state_.sources;++i)
      if(state_.cursors[i].id==o.source &&
         state_.cursors[i].epoch==o.source_epoch){source_index=i;break;}
    if(source_index==kMaxSources)return Status::source_full;
    if(source_index<state_.sources){
      const auto& source=state_.cursors[source_index];
      if(source.clock_domain!=o.clock_domain)return Status::unauthorized;
      if(source.has_sequence){
        if(o.sequence==source.last_sequence)return Status::duplicate;
        if(o.sequence<source.last_sequence || o.acquired_ns<source.last_acquired_ns)
          return Status::out_of_order;
      }
    }
    std::size_t index=state_.count;
    for(std::size_t i=0;i<state_.count;++i)
      if(same_key(state_.values[i],o)){index=i;break;}
    if(index==kMaxMetrics)return Status::state_full;
    // New source+metric observations in different clock domains are not used
    // to infer biological causality. Source revision is the ordering authority.
    bool gap=false;
    if(source_index==state_.sources){
      state_.cursors[state_.sources++]={o.source,o.clock_domain,0,0,false,false,o.source_epoch};
    }
    auto& cursor=state_.cursors[source_index];
    if(cursor.has_sequence&&o.sequence>cursor.last_sequence+1){gap=true;cursor.gap=true;++state_.sequence_gaps;}
    cursor.has_sequence=true;
    cursor.last_sequence=o.sequence;cursor.last_acquired_ns=o.acquired_ns;
    if(index==state_.count)++state_.count;
    auto& m=state_.values[index];
    m={o.colony,o.animon,o.source,o.metric,o.value,o.origin,
       gap?Quality::degraded:Quality::current,o.sequence,o.acquired_ns,o.evidence_tag,
       o.source_epoch};
    ++state_.committed_updates;++state_.revision;
    revision=state_.revision;
    } // Release the mutex before notifying extensions.
    if(extension_)extension_->on_service_event({contracts::ServiceId::colony_projector,
      contracts::ServicePhase::committed,revision,o.animon,0});
    return Status::ok;
  }
  // A copy under a short mutex hold gives readers a consistent revision;
  // callbacks, JSON and filesystem activity happen AFTER the lock is released.
  ColonyState snapshot(std::uint64_t now_ns,std::uint64_t max_age_ns) const noexcept {
    ColonyState copy;
    {
      std::lock_guard<std::mutex> lock(mutex_);
      copy=state_;
    }
    for(std::size_t i=0;i<copy.count;++i){
      auto& m=copy.values[i];
      if(now_ns>=m.acquired_ns&&now_ns-m.acquired_ns>max_age_ns)
        m.quality=Quality::stale;
      // A newer source incarnation supersedes the old reading, even when
      // its original wall clock or tick domain has not expired yet.
      for(std::size_t j=0;j<copy.sources;++j)
        if(copy.cursors[j].id==m.source&&copy.cursors[j].epoch>m.source_epoch)
          m.quality=Quality::stale;
    }
    return copy;
  }
  std::uint64_t revision() const noexcept {
    std::lock_guard<std::mutex> lock(mutex_);
    return state_.revision;
  }
};
} // namespace anaiero::runtime
